class Garage {
    private int[] slots;
    private int used;
    public Garage(int n) {
        slots = new int[n];
    }
    public boolean park(int id) {
        for (int i = 0; i < slots.length; i++) {
            if (slots[i] == 0) {
                slots[i] = id;
                used++;
                return true;
            }
        }
        return false;
    }
    public void leave(int id) {
        for (int i = 0; i < slots.length; i++) {
            if (slots[i] == id) {
                slots[i] = 0;
                used--;
            }
        }
    }
    // other methods not shown
}
```

